/** All Maharashtra places: cities and towns first, then destinations. Ids are unique across both tables. */
export const ALL_MAHARASHTRA_PLACES: Destination[] = [...MAHARASHTRA_CITIES, ...MAHARASHTRA_DESTINATIONS];

export function destinationById(id: string): Destination | undefined {
  return ALL_MAHARASHTRA_PLACES.find((d) => d.id === id);
}
